import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Creator","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/creator.md","filePath":"03-developer/models/creator.md"}`),a={name:`03-developer/models/creator.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="creator" tabindex="-1">Creator <a class="header-anchor" href="#creator" aria-label="Permalink to “Creator”">​</a></h1><p><strong>Model purpose:</strong> This model is used to define a product creator. Depending on the type of store, a creator can be a product brand, such as Samsung or Apple, or a person, such as an author or translator. Therefore, its use is not limited to commercial brands; it can be used for various types of stores and product catalogs.</p><h2 id="table-creators" tabindex="-1">Table: <code>creators</code> <a class="header-anchor" href="#table-creators" aria-label="Permalink to “Table: creators”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Comment</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique creator identifier</td></tr><tr><td><code>name</code></td><td>TEXT</td><td>No</td><td>Creator name</td></tr><tr><td><code>slug</code></td><td>VARCHAR(128)</td><td>No</td><td>Unique text identifier for the creator URL</td></tr><tr><td><code>subtitle</code></td><td>TEXT</td><td>Yes</td><td>Creator subtitle</td></tr><tr><td><code>description</code></td><td>LONGTEXT</td><td>Yes</td><td>Creator description</td></tr><tr><td><code>image</code></td><td>VARCHAR(2048)</td><td>Yes</td><td>Creator image</td></tr><tr><td><code>parent_id</code></td><td>INT UNSIGNED</td><td>Yes</td><td>Parent creator identifier</td></tr><tr><td><code>canonical</code></td><td>TEXT</td><td>Yes</td><td>Canonical URL of the creator page</td></tr><tr><td><code>sort</code></td><td>INT</td><td>No</td><td>Creator display order</td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record soft-deletion time</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Record creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time of the last update</td></tr><tr><td><code>markups</code></td><td>TEXT</td><td>Yes</td><td>Schema Markup settings for the creator page</td></tr></tbody></table><h2 id="additional-field-details" tabindex="-1">Additional Field Details <a class="header-anchor" href="#additional-field-details" aria-label="Permalink to “Additional Field Details”">​</a></h2><ul><li><code>name</code>, <code>subtitle</code>, and <code>description</code>: These fields are translatable.</li><li><code>slug</code>: A unique value used to identify the creator in the web page URL.</li><li><code>image</code>: Specifies the creator image; the optimized and original versions are served from different paths.</li><li><code>parent_id</code>: Enables a hierarchical structure between creators; for example, creating creators that are subordinate to another creator.</li><li><code>canonical</code>: Stores the canonical URL of the creator page and can be used to manage the preferred page URL for search engines.</li><li><code>sort</code>: Specifies the creator&#39;s display order.</li><li><code>markups</code>: Stores custom Schema Markup settings for the creator page.</li></ul><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="translatable-name-subtitle-description" tabindex="-1"><code>$translatable = [&#39;name&#39;, &#39;subtitle&#39;, &#39;description&#39;]</code> <a class="header-anchor" href="#translatable-name-subtitle-description" aria-label="Permalink to “$translatable = [&#39;name&#39;, &#39;subtitle&#39;, &#39;description&#39;]”">​</a></h3><p>Specifies that the creator&#39;s name, subtitle, and description use the model&#39;s translation system and can have different values in different languages.</p><h3 id="markupkeywords" tabindex="-1"><code>markupKeywords()</code> <a class="header-anchor" href="#markupkeywords" aria-label="Permalink to “markupKeywords()”">​</a></h3><p>Provides the variables available for use in the creator&#39;s Schema Markup settings as an array of labels and values.</p><p>Variables defined in the current code:</p><ul><li><code>app.name</code>: The application name from <code>config(&#39;app.name&#39;)</code>.</li><li><code>name</code>: The creator name from the model&#39;s <code>name</code> field.</li></ul><h3 id="findorcreate-values-type-null-locale-null" tabindex="-1"><code>findOrCreate($values, $type = null, $locale = null)</code> <a class="header-anchor" href="#findorcreate-values-type-null-locale-null" aria-label="Permalink to “findOrCreate($values, $type = null, $locale = null)”">​</a></h3><p>Finds or creates a creator based on a string, array, or collection of values. This method simplifies assigning a creator when creating or editing a product and supports working with multiple creators in a single call.</p><ul><li>If the input value is a <code>Creator</code> instance, that instance is used.</li><li>Otherwise, each value is passed to <code>findOrCreateFromString()</code>.</li><li>If the input is a string, a single creator is returned; otherwise, a collection of results is returned.</li></ul><h3 id="findfromstring-name-type-null-locale-null" tabindex="-1"><code>findFromString($name, $type = null, $locale = null)</code> <a class="header-anchor" href="#findfromstring-name-type-null-locale-null" aria-label="Permalink to “findFromString($name, $type = null, $locale = null)”">​</a></h3><p>Searches for an existing creator by name or <code>slug</code> in the specified language. If no language is specified, the model&#39;s current language is used. Returns <code>null</code> if no creator is found.</p><p>The <code>$type</code> parameter is not used in the search condition in the current version of the code.</p><h3 id="findorcreatefromstring-name-type-null-locale-null" tabindex="-1"><code>findOrCreateFromString($name, $type = null, $locale = null)</code> <a class="header-anchor" href="#findorcreatefromstring-name-type-null-locale-null" aria-label="Permalink to “findOrCreateFromString($name, $type = null, $locale = null)”">​</a></h3><p>Searches for a creator by name or <code>slug</code> and creates a new record if none exists. When creating the record, the name is saved in the selected language and the <code>slug</code> is generated using the <code>sluger()</code> function.</p><p>The <code>$type</code> parameter is also not used to create the record in the current version of the code.</p><h3 id="children" tabindex="-1"><code>children()</code> <a class="header-anchor" href="#children" aria-label="Permalink to “children()”">​</a></h3><p>Defines a <code>hasMany</code> relationship with the <code>Creator</code> model through the <code>parent_id</code> field and returns the creators subordinate to this creator.</p><h3 id="getroutekeyname" tabindex="-1"><code>getRouteKeyName()</code> <a class="header-anchor" href="#getroutekeyname" aria-label="Permalink to “getRouteKeyName()”">​</a></h3><p>Sets the <code>slug</code> field as the model&#39;s route key so the creator can be identified in routes by its text identifier.</p><h3 id="imgurl" tabindex="-1"><code>imgUrl()</code> <a class="header-anchor" href="#imgurl" aria-label="Permalink to “imgUrl()”">​</a></h3><p>Returns the URL of the optimized creator image. If no image is defined, it returns the URL of the site&#39;s default logo.</p><h3 id="imgoriginalurl" tabindex="-1"><code>imgOriginalUrl()</code> <a class="header-anchor" href="#imgoriginalurl" aria-label="Permalink to “imgOriginalUrl()”">​</a></h3><p>Returns the URL of the original creator image. If no image is defined, it returns the URL of the site&#39;s default logo.</p><h3 id="attachs" tabindex="-1"><code>attachs()</code> <a class="header-anchor" href="#attachs" aria-label="Permalink to “attachs()”">​</a></h3><p>Defines a polymorphic (<code>morphMany</code>) relationship with the <a href="./attachment.html">Attachment</a> model and returns the attachments associated with the creator.</p><h3 id="weburl" tabindex="-1"><code>webUrl()</code> <a class="header-anchor" href="#weburl" aria-label="Permalink to “webUrl()”">​</a></h3><p>Builds the public creator page URL using the <code>client.creator</code> route and sets the URL language with <code>fixUrlLang()</code>.</p><h3 id="products" tabindex="-1"><code>products()</code> <a class="header-anchor" href="#products" aria-label="Permalink to “products()”">​</a></h3><p>Defines a many-to-many (<code>belongsToMany</code>) relationship with the <a href="./product.html">Product</a> model and returns the products associated with the creator.</p><h3 id="evaluations" tabindex="-1"><code>evaluations()</code> <a class="header-anchor" href="#evaluations" aria-label="Permalink to “evaluations()”">​</a></h3><p>Retrieves the related evaluations from the <a href="./evaluation.html">Evaluation</a> model. The results include public evaluations without a specific association, evaluations for the <code>Creator</code> type without a specified identifier, and evaluations specific to this creator.</p><h3 id="parent" tabindex="-1"><code>parent()</code> <a class="header-anchor" href="#parent" aria-label="Permalink to “parent()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <code>Creator</code> model through <code>parent_id</code> and returns the parent creator.</p><h3 id="markup" tabindex="-1"><code>markup()</code> <a class="header-anchor" href="#markup" aria-label="Permalink to “markup()”">​</a></h3><p>Generates or returns the Schema Markup for the creator page so that structured information about the page can be provided to search engines.</p>`,42)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};